import { monthlyCents, nextCharge, CYCLE } from './src/cycles.js';

// Test 1: Weekly plan cost calculation
const weeklyPlan = { name: 'Meal kit', price: 5990, cycle: CYCLE.WEEK };
const monthlyCost = monthlyCents(weeklyPlan);
console.log(`Weekly €59.90 costs €${(monthlyCost / 100).toFixed(2)} per month`);
console.log(`Expected: €${(59.90 * 52 / 12).toFixed(2)}`);
console.log(`Match: ${Math.abs(monthlyCost - Math.round(59.90 * 52 / 12 * 100)) < 1}`);

// Test 2: Next charge calculation
const today = '2026-10-25';
const since = '2026-10-20';
const next1 = nextCharge({ cycle: CYCLE.WEEK, since }, today);
console.log(`\nNext charge from ${today} for plan starting ${since}: ${next1}`);
console.log(`Expected: 2026-10-27 (7 days after 2026-10-20)`);

// Test 3: Multiple charges
const since2 = '2026-10-20';
let current = since2;
const charges = [];
for (let i = 0; i < 4; i++) {
  current = i === 0 ? since2 : new Date(new Date(current).getTime() + 7 * 24 * 60 * 60 * 1000).toISOString().slice(0, 10);
  charges.push(current);
}
console.log(`\nWeekly charges starting 2026-10-20:`);
charges.forEach((c, i) => console.log(`  ${i + 1}: ${c}`));
EOF
